<?phpnamespace mohe\basic;use app\Request;use mohe\utils\JwtAuth;use think\facade\App;use think\helper\Str;class BaseAuth{    /**     * @param array $whereKey     * @param $class     * 识别哪些key在搜索器里面 哪些不在搜索器里面     */    public function ________($whereKey,$class){        $inKeys=[];        $outKeys=[];        foreach ($whereKey as $key){            $method    = 'search' . Str::studly($key) . 'Attr';            if (method_exists($class, $method)) {                $inKeys[]=$key;            } else{                $outKeys[]=$key;            }        }        return [$inKeys,$outKeys];    }    /**     * 减库存 加销量     */    public function _____($model,array $where, int $num, string $stock = 'stock', string $sales = 'sales'){        $stockNum=$model->where($where)->value($stock);        $decNum=$num;        if($stockNum <= 0) {            $decNum=0;        }        return $model->where($where)->dec($stock,$decNum)->inc($sales,$num)->update();    }    /**     *  加库存减销量     */    public function ___($model,array $where, int $num, string $stock = 'stock', string $sales = 'sales'){        $stockNum=$model->where($where)->value($sales);        $decNum=$num;        if($stockNum <= 0) {            $decNum=0;        }        return $model->where($where)->inc($stock,$num)->dec($sales,$decNum)->update();    }    public function parseToken($token,$function){        $jwtAuth = app()->make(JwtAuth::class);        [$id, $type, $auth] = $jwtAuth->parseToken($token);        $adminInfo=$function($id);        $adminInfo->type=$type;        $adminInfo->auth=$auth;        return $adminInfo;    }}